import { useState } from "react";
import axios from "axios";

export default function Cadastro() {
  const [form, setForm] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
  });
  const [foto, setFoto] = useState(null);
  const [mensagem, setMensagem] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleFile = (e) => {
    setFoto(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    Object.entries(form).forEach(([chave, valor]) => {
      formData.append(chave, valor);
    });
    formData.append("foto", foto);

    try {
      await axios.post("http://localhost:3001/usuarios", formData);
      setMensagem("Usuário cadastrado com sucesso!");
      setForm({
        nome: "",
        idade: "",
        rua: "",
        bairro: "",
        estado: "",
        biografia: "",
      });
      setFoto(null);
    } catch (err) {
      setMensagem("Erro ao cadastrar usuário.");
      console.error(err);
    }
  };

  return (
    <div className="container mt-4">
      <h3 className="mb-4">Cadastrar Usuário</h3>

      {mensagem && (
        <div className={`alert ${mensagem.includes("Erro") ? "alert-danger" : "alert-success"}`}>
          {mensagem}
        </div>
      )}

      <form onSubmit={handleSubmit} encType="multipart/form-data">
        <div className="row mb-3">
          <div className="col-md-4">
            <input
              type="text"
              name="nome"
              className="form-control"
              placeholder="Nome"
              value={form.nome}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-2">
            <input
              type="number"
              name="idade"
              className="form-control"
              placeholder="Idade"
              value={form.idade}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-3">
            <input
              type="text"
              name="rua"
              className="form-control"
              placeholder="Rua"
              value={form.rua}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-3">
            <input
              type="text"
              name="bairro"
              className="form-control"
              placeholder="Bairro"
              value={form.bairro}
              onChange={handleChange}
              required
            />
          </div>
        </div>

        <div className="row mb-3">
          <div className="col-md-4">
            <input
              type="text"
              name="estado"
              className="form-control"
              placeholder="Estado"
              value={form.estado}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-8">
            <textarea
              name="biografia"
              className="form-control"
              placeholder="Biografia"
              value={form.biografia}
              onChange={handleChange}
              rows={2}
            />
          </div>
        </div>

        <div className="mb-3">
          <input
            type="file"
            name="foto"
            className="form-control"
            accept="image/*"
            onChange={handleFile}
            required
          />
        </div>

        <button type="submit" className="btn btn-success">
          Cadastrar
        </button>
      </form>
    </div>
  );
}
